package net.civeira.phylax.feature.observe.observedembed.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;
import net.civeira.phylax.feature.observe.observedembed.domain.valueobject.PanelUidVO;

class PanelUidValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of panel uid of observed embed")
  void test_panel_uid_value_holder_assign_plain_value() {
    Object holder = new Object();
    PanelUidValueHolder<Object> value = new PanelUidValueHolder<>(holder);
    Assertions.assertSame(holder, value.panelUid("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPanelUidValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getPanelUid().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.panelUidNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPanelUidValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPanelUid().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of panel uid of observed embed")
  void test_panel_uid_value_holder_assign_value_object() {
    Object holder = new Object();
    PanelUidValueHolder<Object> value = new PanelUidValueHolder<>(holder);
    PanelUidVO vo = PanelUidVO.from("one");
    Assertions.assertFalse(value.getPanelUidValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.panelUid(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPanelUidValue().orElseThrow());
    Assertions.assertSame(holder, value.panelUid(Optional.empty()));
    Assertions.assertFalse(value.getPanelUidValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.panelUid(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPanelUidValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of panel uid of observed embed against the original")
  void test_panel_uid_value_holder_read() {
    Object holder = new Object();
    PanelUidValueHolder<Object> value = new PanelUidValueHolder<>(holder);
    PanelUidVO vo = PanelUidVO.from("one");
    PanelUidVO other = PanelUidVO.from("one");
    ObservedEmbed original = Mockito.mock(ObservedEmbed.class);
    Mockito.when(original.getPanelUidValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPanelUid(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPanelUid(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.panelUid(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPanelUid(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPanelUid(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of panel uid of observed embed")
  void test_panel_uid_value_holder_unset() {
    Object holder = new Object();
    PanelUidValueHolder<Object> value = new PanelUidValueHolder<>(holder);
    PanelUidVO vo = PanelUidVO.from("one");
    value.panelUid(vo);
    Assertions.assertSame(holder, value.unsetPanelUidIfMatches("panelUid_other"));
    Assertions.assertTrue(value.getPanelUidValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPanelUidIfMatches("panelUid"));
    Assertions.assertFalse(value.getPanelUidValue().isPresent(),
        "The field name must clear the value");
    value.panelUid(vo);
    Assertions.assertSame(holder, value.unsetPanelUid());
    Assertions.assertFalse(value.getPanelUidValue().isPresent(), "Unset must clear the value");
  }
}
